function mat(c,r=.75){return new THREE.MeshStandardMaterial({color:c,roughness:r,metalness:.12});}
function mesh(g,m,parent,x=0,y=0,z=0){const o=new THREE.Mesh(g,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
function box(p,w,h,d,m,x=0,y=0,z=0){return mesh(new THREE.BoxGeometry(w,h,d),m,p,x,y,z);}
function ellipsoid(p,rx,ry,rz,m,x=0,y=0,z=0){const a=mesh(new THREE.SphereGeometry(1,28,16),m,p,x,y,z);a.scale.set(rx,ry,rz);return a;}
function foil(p,points,depth,m){const s=new THREE.Shape();s.moveTo(points[0][0],points[0][1]);for(const v of points.slice(1))s.lineTo(v[0],v[1]);s.closePath();const g=new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:false});g.rotateX(Math.PI/2);return mesh(g,m,p);}
