function render(now){requestAnimationFrame(render);const dt=Math.min((now-last)/1000,.05);last=now;if(active){if(!paused&&!finished)update(dt);if(cockpitView){offset.set(0,3,-29).applyEuler(aircraft.rotation);camera.position.copy(aircraft.position).add(offset);target.set(0,airborne?3:-15,-600).applyEuler(aircraft.rotation).add(aircraft.position);camera.lookAt(target);camera.rotateZ(roll*.4);}else{offset.fromArray([[18,17,91],[86,17,10],[57,16,-80],[-86,17,10]][cameraAngle]);if(!airborne&&cameraAngle===0)offset.set(22,35,105);offset.multiplyScalar(model==='an225'?1.12:1);if(camera.aspect<1)offset.multiplyScalar(1/camera.aspect);offset.applyAxisAngle(new THREE.Vector3(0,1,0),yaw);camDesired.copy(aircraft.position).add(offset);camera.position.lerp(camDesired,1-Math.exp(-dt*4));target.copy(aircraft.position);target.y+=4;camera.lookAt(target);}sun.position.copy(aircraft.position).add(new THREE.Vector3(-500,900,400));sun.target.position.copy(aircraft.position);if(now>radioUntil)$('radioText').classList.remove('show');}else{aircraft.visible=true;aircraft.rotation.y=-.5;const mobile=innerWidth<1000;camera.position.set(mobile?95:80,mobile?34:28,mobile?495:467);target.set(mobile?0:24,mobile?10:12,380);camera.lookAt(target);fans.forEach(f=>f.rotation.z+=dt*.2);}renderer.autoClear=true;renderer.render(scene,camera);if(active&&cockpitView){flightdeck.resize(camera.aspect);flightdeck.update({speed:velocity*1.944,altitude:Math.max(0,aircraft.position.y-7),pitch,roll,yaw,throttle,engines,type:model,gear,failed,controlPitch:(keys.has('ArrowDown')?1:0)-(keys.has('ArrowUp')?1:0),controlRoll:(keys.has('ArrowLeft')?1:0)-(keys.has('ArrowRight')?1:0)});renderer.autoClear=false;renderer.clearDepth();renderer.render(flightdeck.scene,flightdeck.camera);renderer.autoClear=true;}}
addEventListener('resize',()=>{renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();});$('loading').classList.add('hidden');requestAnimationFrame(render);


